// Sample files (generated by scripts/make-samples.ts) and their extracted text.
import texts from "@/data/sample-texts.json";
import type { Attachment } from "./types";
import { joinWrappedLines } from "./joinLines";

type T = { kind: Attachment["kind"]; pages: string[][]; sheets?: Attachment["sheets"] };
const TEXTS = texts as unknown as Record<string, T>;

export const SAMPLE_FILES = Object.keys(TEXTS);

export function sampleAttachment(name: string, id: string): Attachment {
  const t = TEXTS[name];
  if (!t) throw new Error(`Unknown sample ${name}`);
  return { id, name, url: `/samples/${name}`, kind: t.kind, pages: t.kind === "pdf" ? t.pages.map(joinWrappedLines) : t.pages, sheets: t.sheets };
}

